R=itest-dropout-01-q1; T0_5=$(guest_epoch) && run_test $R 42 --scenario dropout-reconnect --duration 180; RT=$?     # the guest epoch before the test's first action bounds its broker log (third line)
[ "$RT" = 0 ] && python3 -c "import json;m=json.load(open('$HOME/egw-tcg/itest/$R/manifest.json'));print(m.get('note'))" || stop "test 5: not evaluated (RT='$RT')"
if [ "$RT" != 0 ]; then stop "test 5: broker log NOT read (RT='$RT')"; elif ! sut_log broker $R "$T0_5"; then stop "test 5: the broker log bounded to this test was NOT read - it shows no connection or disconnection, nor their absence"; elif grep -E "egw-simulator-$R" ~/egw-tcg/itest/$R.sut/broker.log > ~/egw-tcg/itest/$R.broker.txt && [ -s ~/egw-tcg/itest/$R.broker.txt ]; then wc -l ~/egw-tcg/itest/$R.broker.txt; else stop "test 5: the broker log bounded to this test holds no line of the client egw-simulator-$R, or $R.broker.txt could not be written"; fi     # the excerpt is taken from the log of THIS test (sut_log: [T0_5, the guest's clock at the read]), never from the broker's whole history, where an earlier execution's lines of the same client id would be counted
